import type { MemoryOperationInput } from "./types.ts";

/** An exact span in an external user message, not text generated by the assistant. */
export function memoryOperationConfirmation(input: Pick<MemoryOperationInput, "action" | "memory_uid" | "expected_revision_uid" | "valid_until">): string {
  if (input.action === "revise") throw new Error("Revision uses the user's exact replacement text instead.");
  if (input.action === "set_expiry" && typeof input.valid_until !== "string") throw new Error("Expiry requires a UTC deadline.");
  return `确认 Anima ${input.action} ${input.memory_uid} ${input.expected_revision_uid}${input.action === "set_expiry" ? ` ${input.valid_until ?? ""}` : ""}`;
}
